# ============================================================================
# NAME: REMEDIATION - WatchGuard Global Template Subscription Update (Simple)
# AUTHORED BY: Cogan Goldwater
# TYPE: Remediation
# SCOPE: Credential Broker / Device 9800 only / non-delegated WatchGuard Subscribers
# VARIABLES:
#   None. Uses newest global evaluation manifest in C:\MME\CS.
# FILE TRANSFERS:
#   None. Requires an existing WatchGuard_Template_Subscriptions_Global_*.json
#   generated by the global evaluation in C:\MME\CS.
# OUTPUT TOKENS:
#   RESULT    | All evaluation TRIGGER Fireboxes verified
#   NO_ACTION | Evaluation manifest has no Fireboxes requiring remediation
#   ERROR     | One or more targeted Fireboxes failed; processing continued
# CUSTOM FIELDS:
#   Reads: opServiceAccountToken (NinjaOne secure field)
#   Writes: None
# LOGGING PATH:
#   C:\MME\AutoLogs\WatchGuard_Template_Subscription_Remediation.log
# REPORT:
#   C:\MME\CS\WatchGuard_Template_Subscription_Remediation_Global_<RunId>.json
# DESCRIPTION:
#   The EVALUATION is the sole scope gate. Only devices marked TRIGGER in the
#   newest clean global manifest are candidates. Delegated, locally managed,
#   NO_ACTION, and unmanifested devices are never written.
#   Remediation gets a fresh subscriber token for each account with candidates,
#   GETs current subscriptions, and either skips an already-compliant device or
#   POSTs ALL current subscriptions plus the target template. Every write is
#   verified by a fresh live GET. It does NOT audit live account inventory,
#   available templates, or subscription equality against the old evaluation.
#   Standard read/auth retries handle HTTP 408/429/500/502/503/504. A failed
#   POST is ALWAYS read back; retry transient HTTP failures only when that
#   read-back confirms original membership unchanged. Never retry HTTP 400,
#   unknown outcomes, failed read-backs, or unexpected subscription changes.
#   ALL per-account/per-device errors are logged and processing CONTINUES.
#   A report is checkpointed before every POST, and final output is ERROR if
#   any target could not be verified. No deployment call; no ordering changes.
#   Exactly one output token; one final exit 0 (NinjaOne safe).
# ============================================================================

[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

$ManifestFilenamePattern = 'WatchGuard_Template_Subscriptions_Global_*.json'
$DesiredTemplateId = 'tmpl_YOUR_TEMPLATE_ID'
$ExpectedProviderId = 'ACC-YOUR_PROVIDER_ID'
$OnePasswordVault = 'MME Automation'
$WatchGuardItemName = 'WatchGuard'
$BootstrapTokenField = 'opServiceAccountToken'
$LogDirectory = 'C:\MME\AutoLogs'
$StagingDirectory = 'C:\MME\CS'
$LogPath = Join-Path $LogDirectory 'WatchGuard_Template_Subscription_Remediation.log'
$RunId = Get-Date -Format 'yyyyMMdd_HHmmss'
$ReportPath = Join-Path $StagingDirectory "WatchGuard_Template_Subscription_Remediation_Global_$RunId.json"
$RetryStatusCodes = @(408, 429, 500, 502, 503, 504)
$RetryDelays = @(2, 5, 10, 20)
$Stage = 'Initialize'
$Outcome = 'ERROR'
$AccountsInScope = 0
$AccountsVisited = 0
$AccountsWithTargets = 0
$AccountsWithErrors = 0
$Targets = 0
$Verified = 0
$Updated = 0
$AlreadyPresent = 0
$WriteAttempts = 0
$SourceManifest = ''
$ManifestRunId = ''
$FailedAccountId = ''
$ApiKey = $null
$ReadWriteAccessId = $null
$ReadWritePassword = $null
$AuthenticationUrl = $null
$BaseApiUrl = $null
$ProviderToken = $null
$ProviderTokenIssuedAt = $null
$SubscriberToken = $null
$ProviderAccountId = ''
$OpExe = $null
$Devices = [System.Collections.Generic.List[object]]::new()
$Errors = [System.Collections.Generic.List[object]]::new()
$FinalOutput = ''

# Proven broker / API helpers retained from tested remediation
function Ensure-Directory([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) {
        New-Item -ItemType Directory -Path $Path -Force | Out-Null
    }
}

function Write-Log([string]$Message) {
    try {
        '{0} | {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Message |
            Add-Content -LiteralPath $LogPath -Encoding UTF8
    }
    catch { }
}

function Get-HttpStatus($ErrorRecord) {
    try {
        if ($null -ne $ErrorRecord.Exception.Response) {
            return [int]$ErrorRecord.Exception.Response.StatusCode
        }
    }
    catch { }
    return $null
}

# Safe only for reads, authentication and audience discovery. Never use for
# the subscription POST because a timed-out mutation may already have applied.
function Invoke-WGSafeApi {
    param(
        [Parameter(Mandatory)][ValidateSet('Get','Post')][string]$Method,
        [Parameter(Mandatory)][string]$Uri,
        [hashtable]$Headers,
        [object]$Body,
        [string]$ContentType,
        [string]$Label = 'API'
    )
    for ($Attempt = 1; $Attempt -le 5; $Attempt++) {
        $Arguments = @{
            Method = $Method
            Uri = $Uri
            TimeoutSec = 75
            ErrorAction = 'Stop'
        }
        if ($null -ne $Headers) { $Arguments.Headers = $Headers }
        if ($null -ne $Body) { $Arguments.Body = $Body }
        if ($ContentType) { $Arguments.ContentType = $ContentType }
        try {
            Start-Sleep -Milliseconds 100
            return Invoke-RestMethod @Arguments
        }
        catch {
            $Http = Get-HttpStatus $_
            if ($Attempt -eq 5 -or $null -eq $Http -or $Http -notin $RetryStatusCodes) {
                throw
            }
            $Delay = $RetryDelays[$Attempt - 1]
            Write-Log ("RETRY | Stage={0} Attempt={1}/5 HTTP={2} DelaySeconds={3}" -f $Label, $Attempt, $Http, $Delay)
            Start-Sleep -Seconds $Delay
        }
    }
}

function Get-OpField($Item, [string]$Label) {
    $Field = @($Item.fields | Where-Object { $_.label -eq $Label -or $_.id -eq $Label } | Select-Object -First 1)
    if ($Field.Count -ne 1 -or [string]::IsNullOrWhiteSpace([string]$Field[0].value)) {
        throw "Required 1Password field unavailable: $Label"
    }
    return ([string]$Field[0].value).Trim()
}

function Get-WGToken([string]$AccessId, [string]$Password, [string]$Audience) {
    $Basic = [Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("${AccessId}:${Password}"))
    $Body = @{ grant_type = 'client_credentials'; scope = 'api-access' }
    if ($Audience) { $Body.audience = $Audience }
    $Response = Invoke-WGSafeApi -Method Post -Uri $AuthenticationUrl `
        -Headers @{Accept='application/json'; Authorization="Basic $Basic"} `
        -ContentType 'application/x-www-form-urlencoded' -Body $Body -Label 'Authentication'
    if ([string]::IsNullOrWhiteSpace([string]$Response.access_token)) {
        throw 'Authentication returned no access_token.'
    }
    return [string]$Response.access_token
}

function Get-WGHeaders([string]$AccessToken) {
    return @{
        Accept = 'application/json'
        'Content-Type' = 'application/json'
        Authorization = "Bearer $AccessToken"
        'WatchGuard-API-Key' = $ApiKey
    }
}

function Assert-UniqueIds([string[]]$Ids, [string]$Label) {
    $Seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    foreach ($Id in @($Ids)) {
        if ([string]::IsNullOrWhiteSpace($Id)) { throw "$Label contains a blank template ID." }
        if (-not $Seen.Add($Id)) { throw "$Label contains duplicate template ID: $Id" }
    }
}

function Test-SameIds([string[]]$Left, [string[]]$Right) {
    if (@($Left).Count -ne @($Right).Count) { return $false }
    $Expected = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    foreach ($Id in @($Left)) { $null = $Expected.Add($Id) }
    if ($Expected.Count -ne @($Left).Count) { return $false }
    foreach ($Id in @($Right)) {
        if (-not $Expected.Remove($Id)) { return $false }
    }
    return ($Expected.Count -eq 0)
}

function Get-LiveSubscriptions([string]$AccountId, [string]$DeviceId, [hashtable]$Headers) {
    if ($DeviceId -match '^FB-(\d+)$') { $QueryId = $Matches[1] }
    elseif ($DeviceId -match '^FBCL-\d+$') { $QueryId = $DeviceId }
    else { throw "Invalid Firebox ID: $DeviceId" }

    $Uri = "$BaseApiUrl/firebox/management/v1/configuration/$AccountId/templates/subscribe?device=$([Uri]::EscapeDataString($QueryId))"
    $Response = Invoke-WGSafeApi -Method Get -Uri $Uri -Headers $Headers -Label "Subscriptions:$DeviceId"
    if ($null -eq $Response -or $Response.PSObject.Properties.Name -notcontains 'templates' -or
        $null -eq $Response.templates) {
        throw "Subscription response missing templates array: $DeviceId"
    }
    $Ids = [System.Collections.Generic.List[string]]::new()
    foreach ($Template in @($Response.templates)) { $Ids.Add([string]$Template.id) | Out-Null }
    $Result = @($Ids.ToArray())
    Assert-UniqueIds -Ids $Result -Label "Live subscriptions for $DeviceId"
    return $Result
}

function Save-AtomicJson([string]$Path, [object]$Document) {
    $Tmp = "$Path.$RunId.tmp"
    try {
        $Document | ConvertTo-Json -Depth 20 |
            Set-Content -LiteralPath $Tmp -Encoding UTF8 -ErrorAction Stop
        Move-Item -LiteralPath $Tmp -Destination $Path -Force -ErrorAction Stop
    }
    finally {
        if (Test-Path -LiteralPath $Tmp) {
            Remove-Item -LiteralPath $Tmp -Force -ErrorAction SilentlyContinue
        }
    }
}



function Get-CurrentProviderHeaders {
    # A global remediation may run for over an hour. Never retain a stale
    # provider token; each subscriber token is acquired per account.
    if ($null -eq $script:ProviderTokenIssuedAt -or
        ((Get-Date) - $script:ProviderTokenIssuedAt).TotalMinutes -ge 40) {
        $script:ProviderToken = Get-WGToken $ReadWriteAccessId $ReadWritePassword ''
        $script:ProviderTokenIssuedAt = Get-Date
        Write-Log 'PROVIDER_TOKEN_REFRESH | Renewed provider authorization'
    }
    return (Get-WGHeaders $script:ProviderToken)
}


function Save-Report {
    $Document = [ordered]@{
        schemaVersion = 1
        action = 'WatchGuardTemplateSubscriptionGlobalRemediation'
        mode = 'MANIFEST_TRIGGER_ONLY_CONTINUE_ON_ERROR'
        runId = $RunId
        capturedAtUtc = [DateTimeOffset]::UtcNow.ToString('yyyy-MM-ddTHH:mm:ssZ')
        outcome = $Outcome
        inputManifest = $SourceManifest
        inputManifestRunId = $ManifestRunId
        targetTemplateId = $DesiredTemplateId
        accountsInScope = $AccountsInScope
        accountsVisited = $AccountsVisited
        accountsWithTargets = $AccountsWithTargets
        accountsWithErrors = $AccountsWithErrors
        targets = $Targets
        verified = $Verified
        updated = $Updated
        alreadyPresent = $AlreadyPresent
        writeAttempts = $WriteAttempts
        devices = @($Devices.ToArray())
        errors = @($Errors.ToArray())
    }
    Save-AtomicJson -Path $ReportPath -Document $Document
}

function Add-Failure([string]$StageName, [string]$AccountId, [string]$DeviceId, [string]$Message, $HttpStatus, [string]$ResponseBody = '') {
    $Errors.Add([PSCustomObject]@{
        stage = $StageName
        accountId = $AccountId
        deviceId = $DeviceId
        httpStatus = $HttpStatus
        message = $Message
        responseBody = $ResponseBody
    }) | Out-Null
    Write-Log "DEVICE_ERROR | Stage=$StageName Account=$AccountId Device=$DeviceId HTTP=$HttpStatus Message=$Message Response=$ResponseBody"
}

# Capture a short API error body to diagnose 400 without logging credentials.
function Get-HttpErrorBody($ErrorRecord) {
    try {
        $Stream = $ErrorRecord.Exception.Response.GetResponseStream()
        if ($null -eq $Stream) { return '' }
        $Reader = [System.IO.StreamReader]::new($Stream)
        $Text = $Reader.ReadToEnd()
        if ($Text.Length -gt 600) { $Text = $Text.Substring(0, 600) }
        return (($Text -replace '[\r\n]+', ' ').Trim())
    }
    catch { return '' }
}

try {
    Ensure-Directory $LogDirectory
    Ensure-Directory $StagingDirectory
    Write-Log "START | Mode=ManifestTriggerOnlyContinueOnError Template=$DesiredTemplateId RunId=$RunId"

    # Only the newest evaluation file, never silently fall back to stale scope.
    $Stage = 'ManifestDiscovery'
    $Candidates = @(Get-ChildItem -LiteralPath $StagingDirectory -Filter $ManifestFilenamePattern -File -ErrorAction Stop |
        Where-Object { $_.Name -cmatch '^WatchGuard_Template_Subscriptions_Global_20\d{6}_\d{6}\.json$' } |
        Sort-Object Name -Descending)
    if ($Candidates.Count -eq 0) { throw "No global evaluation manifest found in $StagingDirectory" }
    $File = $Candidates[0]
    $SourceManifest = [string]$File.FullName
    $ApprovedRunId = [string]($File.BaseName -creplace '^WatchGuard_Template_Subscriptions_Global_', '')
    $Stage = 'SourceManifest'
    $Source = Get-Content -LiteralPath $SourceManifest -Raw -Encoding UTF8 | ConvertFrom-Json
    $ManifestRunId = [string]$Source.runId
    if ([int]$Source.schemaVersion -ne 2 -or
        $Source.mode -cne 'READ_ONLY_GLOBAL' -or
        $Source.outcome -notin @('TRIGGER','NO_ACTION') -or
        $ManifestRunId -cne $ApprovedRunId -or
        $Source.scope.scopeMode -cne 'GLOBAL_NON_DELEGATED_SUBSCRIBERS' -or
        $Source.providerAccountId -cne $ExpectedProviderId -or
        $Source.target.templateId -cne $DesiredTemplateId -or
        $Source.target.ownerAccountId -cne $ExpectedProviderId -or
        $Source.target.matchingRule -cne 'EXACT_TEMPLATE_ID_MEMBERSHIP_ONLY' -or
        [int]$Source.summary.errors -ne 0 -or
        [int]$Source.summary.managementUnknown -ne 0) {
        throw 'Evaluation manifest identity, scope, target, or outcome invalid. No writes.'
    }

    $AllAccounts = @($Source.accounts)
    $EligibleAccounts = @($AllAccounts | Where-Object { $_.relationName -ine 'Delegated' } | Sort-Object accountId)
    $AccountsInScope = $EligibleAccounts.Count
    $ScopedIds = @($Source.scope.accountIds | ForEach-Object { [string]$_ })
    $EligibleIds = @($EligibleAccounts | ForEach-Object { [string]$_.accountId })
    Assert-UniqueIds -Ids $ScopedIds -Label 'Evaluation scoped account IDs'
    Assert-UniqueIds -Ids $EligibleIds -Label 'Evaluation eligible account IDs'
    if ($AccountsInScope -lt 1 -or
        $AllAccounts.Count -ne [int]$Source.scope.subscribersDiscovered -or
        $AccountsInScope -ne [int]$Source.summary.accountsInScope -or
        $AccountsInScope -ne [int]$Source.scope.eligibleNonDelegatedSubscribers -or
        -not (Test-SameIds -Left $ScopedIds -Right $EligibleIds)) {
        throw 'Evaluation account scope invalid. No writes.'
    }

    # Manifest status is the gate. Nothing is rediscovered in remediation.
    $Work = [System.Collections.Generic.List[object]]::new()
    foreach ($Account in $EligibleAccounts) {
        $TriggerDevices = @($Account.devices | Where-Object { $_.status -ceq 'TRIGGER' })
        foreach ($Device in $TriggerDevices) {
            $Id = [string]$Device.deviceId
            if ($Device.cloudManaged -ine 'yes' -or
                $Device.targetTemplateId -cne $DesiredTemplateId -or
                [bool]$Device.targetSubscribed -or
                $Id -notmatch '^FB-\d+$') {
                throw "Malformed TRIGGER device in evaluator manifest: $($Account.accountId) / $Id. No writes."
            }
            $Work.Add([PSCustomObject]@{ accountId=[string]$Account.accountId; deviceId=$Id }) | Out-Null
        }
    }
    $Targets = $Work.Count
    $WorkIds = @($Work.ToArray() | ForEach-Object { [string]$_.deviceId })
    Assert-UniqueIds -Ids $WorkIds -Label 'Evaluation TRIGGER devices'
    if ($Targets -ne [int]$Source.summary.cloudDevicesMissingTarget -or
        ($Source.outcome -ceq 'TRIGGER' -and $Targets -eq 0) -or
        ($Source.outcome -ceq 'NO_ACTION' -and $Targets -gt 0)) {
        throw 'Evaluation TRIGGER count or outcome inconsistent. No writes.'
    }
    Write-Log "MANIFEST_VALID | File=$SourceManifest Accounts=$AccountsInScope Targets=$Targets"
    $Stage = 'SaveInitialReport'
    $Outcome = 'IN_PROGRESS'
    Save-Report

    if ($Targets -gt 0) {
        # Credential Broker 9800: same 1Password and WatchGuard auth flow.
    $Stage = 'NinjaSecureField'
    $Bootstrap = [string](Ninja-Property-Get -Name $BootstrapTokenField)
    if ([string]::IsNullOrWhiteSpace($Bootstrap)) { throw 'Ninja secure custom field is empty.' }
    $env:OP_SERVICE_ACCOUNT_TOKEN = $Bootstrap.Trim()
    $Bootstrap = $null

    $Stage = 'OnePasswordCLI'
    foreach ($Candidate in @('C:\Program Files\1Password CLI\op.exe','C:\Program Files\1Password\op.exe')) {
        if (Test-Path -LiteralPath $Candidate) { $OpExe = $Candidate; break }
    }
    if (-not $OpExe) {
        $Command = Get-Command 'op.exe' -ErrorAction SilentlyContinue
        if ($Command) { $OpExe = $Command.Source }
    }
    if (-not $OpExe) { throw '1Password CLI not found.' }
    $null = & $OpExe whoami --format json 2>&1
    if ($LASTEXITCODE -ne 0) { throw '1Password CLI authentication failed.' }

    $Stage = 'WatchGuardCredentials'
    $Raw = & $OpExe item get $WatchGuardItemName --vault $OnePasswordVault --format json 2>&1
    if ($LASTEXITCODE -ne 0) { throw 'Unable to retrieve WatchGuard 1Password item.' }
    $Item = ($Raw -join "`n") | ConvertFrom-Json
    $ApiKey = Get-OpField $Item 'credential'
    $ReadWriteAccessId = Get-OpField $Item 'readWriteAccessId'
    $ReadWritePassword = Get-OpField $Item 'readWritePassword'
    $ProviderAccountId = Get-OpField $Item 'accountID'
    $AuthenticationUrl = (Get-OpField $Item 'authenticationUrl').TrimEnd('/')
    $BaseApiUrl = (Get-OpField $Item 'baseApiUrl').TrimEnd('/')
    $Raw = $null
    $Item = $null
    $env:OP_SERVICE_ACCOUNT_TOKEN = $null
    if ($ProviderAccountId -cne $ExpectedProviderId) { throw 'Broker provider identity mismatch.' }



        foreach ($Account in $EligibleAccounts) {
            $AccountId = [string]$Account.accountId
            $FailedAccountId = $AccountId
            $AccountsVisited++
            $CandidatesForAccount = @($Account.devices | Where-Object { $_.status -ceq 'TRIGGER' } | Sort-Object deviceId)
            if ($CandidatesForAccount.Count -eq 0) { continue }
            $AccountsWithTargets++
            $AccountHadError = $false
            $Headers = $null
            $SubscriptionBaseUri = "$BaseApiUrl/firebox/management/v1/configuration/$AccountId/templates/subscribe"

            # If auth fails, record every candidate, then continue to the next account.
            try {
                $Stage = "SubscriberAudience:$AccountId"
                $ProviderHeaders = Get-CurrentProviderHeaders
                $Audience = Invoke-WGSafeApi -Method Post -Uri "$BaseApiUrl/platform/authorization/v1/audiences" `
                    -Headers $ProviderHeaders -Body (@{accountId=$AccountId} | ConvertTo-Json -Compress) `
                    -ContentType 'application/json' -Label "SubscriberAudience:$AccountId"
                if ([string]::IsNullOrWhiteSpace([string]$Audience.audience)) { throw 'Subscriber audience missing.' }
                $Stage = "SubscriberAuthentication:$AccountId"
                $SubscriberToken = Get-WGToken $ReadWriteAccessId $ReadWritePassword ([string]$Audience.audience)
                $Headers = Get-WGHeaders $SubscriberToken
                $SubscriberToken = $null
            }
            catch {
                $AccountHadError = $true
                $Http = Get-HttpStatus $_
                $Message = [string]$_.Exception.Message
                foreach ($Device in $CandidatesForAccount) {
                    $Record = [PSCustomObject]@{
                        accountId=$AccountId; accountName=[string]$Account.accountName
                        deviceId=[string]$Device.deviceId; deviceName=[string]$Device.deviceName
                        result='SKIPPED_ACCOUNT_AUTH'; beforeIds=@(); intendedIds=@(); verifiedIds=@(); attempts=0
                    }
                    $Devices.Add($Record) | Out-Null
                    Add-Failure -StageName $Stage -AccountId $AccountId -DeviceId $Record.deviceId -Message $Message -HttpStatus $Http
                }
                $AccountsWithErrors++
                $Outcome = 'IN_PROGRESS'
                Save-Report
                continue
            }

            foreach ($Device in $CandidatesForAccount) {
                $Id = [string]$Device.deviceId
                $Record = [PSCustomObject]@{
                    accountId=$AccountId; accountName=[string]$Account.accountName
                    deviceId=$Id; deviceName=[string]$Device.deviceName
                    result='NOT_STARTED'; beforeIds=@(); intendedIds=@(); verifiedIds=@(); attempts=0
                }
                $Devices.Add($Record) | Out-Null
                $Http = $null
                $ErrorBody = ''
                try {
                    $Stage = "ReadBeforeWrite:${AccountId}:$Id"
                    $Before = @(Get-LiveSubscriptions -AccountId $AccountId -DeviceId $Id -Headers $Headers)
                    $Record.beforeIds = @($Before)
                    if ($DesiredTemplateId -cin $Before) {
                        $Record.result = 'ALREADY_PRESENT'
                        $Record.verifiedIds = @($Before)
                        $AlreadyPresent++
                        $Verified++
                        Write-Log "ALREADY_PRESENT | Account=$AccountId Device=$Id NoPOST=True"
                    }
                    else {
                        if ($Before.Count -ge 50) { throw "Template subscription limit reached on $Id" }
                        $Intended = @($Before) + @($DesiredTemplateId)
                        $Record.intendedIds = @($Intended)
                        $NumericId = $Id.Substring(3)
                        $Payload = @{device=$NumericId;templates=@($Intended)} | ConvertTo-Json -Compress -Depth 5
                        $MutationVerified = $false

                        # POST retries only when a known transient error is followed
                        # by a clean read proving NO change in subscriptions.
                        for ($Attempt = 1; $Attempt -le 5; $Attempt++) {
                            $Stage = "SubscriptionWrite:${AccountId}:$Id"
                            $Record.result = 'POST_PENDING_VERIFICATION'
                            $Record.attempts++
                            $WriteAttempts++
                            Save-Report  # Persist intent BEFORE each POST.
                            Write-Log "SUBSCRIPTION_POST | Account=$AccountId Device=$Id Attempt=$Attempt/5 Templates=$($Intended.Count)"
                            $PostError = $null
                            $PostHttp = $null
                            $PostBody = ''
                            try {
                                Start-Sleep -Milliseconds 100
                                $null = Invoke-RestMethod -Method Post -Uri $SubscriptionBaseUri -Headers $Headers `
                                    -Body $Payload -ContentType 'application/json' -TimeoutSec 75 -ErrorAction Stop
                            }
                            catch {
                                $PostError = $_
                                $PostHttp = Get-HttpStatus $_
                                $PostBody = Get-HttpErrorBody $_
                                Write-Log "POST_RESPONSE_ERROR | Account=$AccountId Device=$Id Attempt=$Attempt/5 HTTP=$PostHttp Body=$PostBody"
                            }

                            # An unreadable response after POST is an uncertain
                            # mutation. Never automatically repeat that write.
                            $Stage = "ReadAfterWrite:${AccountId}:$Id"
                            $After = @(Get-LiveSubscriptions -AccountId $AccountId -DeviceId $Id -Headers $Headers)
                            $Record.verifiedIds = @($After)
                            if (Test-SameIds -Left $Intended -Right $After) {
                                $Record.result = if ($null -eq $PostError) { 'UPDATED_VERIFIED' } else { 'UPDATED_VERIFIED_AFTER_API_ERROR' }
                                $Updated++
                                $Verified++
                                $MutationVerified = $true
                                Write-Log "VERIFIED | Account=$AccountId Device=$Id ExistingPreserved=$($Before.Count) TargetPresent=True Total=$($After.Count)"
                                break
                            }
                            if ($null -eq $PostError) {
                                throw "POST returned success but subscriptions did not verify: $Id. NO automatic re-POST."
                            }
                            if ($PostHttp -in $RetryStatusCodes -and
                                (Test-SameIds -Left $Before -Right $After) -and
                                $Attempt -lt 5) {
                                $Delay = $RetryDelays[$Attempt - 1]
                                Write-Log "RETRY | Stage=SubscriptionWrite Account=$AccountId Device=$Id HTTP=$PostHttp Attempt=$Attempt/5 ReadbackUnchanged=True DelaySeconds=$Delay"
                                Start-Sleep -Seconds $Delay
                                continue
                            }
                            $Http = $PostHttp
                            $ErrorBody = $PostBody
                            throw "POST failed/unverified: $Id HTTP=$PostHttp Attempt=$Attempt. NO unsafe retry."
                        }
                        if (-not $MutationVerified) { throw "POST retries exhausted/unverified: $Id" }
                    }
                }
                catch {
                    $AccountHadError = $true
                    if ($null -eq $Http) { $Http = Get-HttpStatus $_ }
                    $Message = [string]$_.Exception.Message
                    if ($Record.result -eq 'POST_PENDING_VERIFICATION') {
                        $Record.result = 'POST_UNVERIFIED'
                    }
                    elseif ($Record.result -eq 'NOT_STARTED') {
                        $Record.result = 'READ_OR_VALIDATION_FAILED'
                    }
                    Add-Failure -StageName $Stage -AccountId $AccountId -DeviceId $Id -Message $Message -HttpStatus $Http -ResponseBody $ErrorBody
                }
                $Outcome = 'IN_PROGRESS'
                Save-Report
            }
            if ($AccountHadError) { $AccountsWithErrors++ }
            Write-Log "ACCOUNT_END | Account=$AccountId Visited=$AccountsVisited/$AccountsInScope Targeted=$($CandidatesForAccount.Count) Verified=$Verified/$Targets Errors=$($Errors.Count)"
            $FailedAccountId = ''
        }
        # All accounts, even those with zero TRIGGER devices, are accounted for.
        # Counting is not an additional remediation eligibility gate.
        $Outcome = if ($Errors.Count -eq 0 -and $Verified -eq $Targets) { 'RESULT' } else { 'ERROR' }
    }
    else {
        $AccountsVisited = $AccountsInScope
        $Outcome = 'NO_ACTION'
    }
}
catch {
    $Http = Get-HttpStatus $_
    $Message = [string]$_.Exception.Message
    Add-Failure -StageName $Stage -AccountId $FailedAccountId -DeviceId '' -Message $Message -HttpStatus $Http
    $Outcome = 'ERROR'
}
finally {
    $env:OP_SERVICE_ACCOUNT_TOKEN = $null
    $ProviderToken = $null
    $SubscriberToken = $null
    $ReadWritePassword = $null
    $ApiKey = $null
    $Headers = $null
    try {
        Ensure-Directory $LogDirectory
        Ensure-Directory $StagingDirectory
        Save-Report
    }
    catch {
        $Outcome = 'ERROR'
        $ReportPath = 'NOT_WRITTEN'
        Write-Log 'ERROR | Stage=FinalReport; report not persisted.'
    }
    Write-Log "END | Outcome=$Outcome ManifestRun=$ManifestRunId AccountsVisited=$AccountsVisited/$AccountsInScope AccountsWithTargets=$AccountsWithTargets AccountsWithErrors=$AccountsWithErrors Targets=$Targets Updated=$Updated AlreadyPresent=$AlreadyPresent Verified=$Verified WriteAttempts=$WriteAttempts Errors=$($Errors.Count) Report=$ReportPath"
    if ($Outcome -eq 'RESULT') {
        $FinalOutput = "RESULT | TemplateSubscriptionsVerified Accounts=$AccountsVisited/$AccountsInScope Targets=$Targets Updated=$Updated AlreadyPresent=$AlreadyPresent Verified=$Verified WriteAttempts=$WriteAttempts Errors=0 Report=$ReportPath"
    }
    elseif ($Outcome -eq 'NO_ACTION') {
        $FinalOutput = "NO_ACTION | NoManifestTriggers Accounts=$AccountsInScope Targets=0 Report=$ReportPath"
    }
    else {
        $FinalOutput = "ERROR | TemplateSubscriptionIncomplete AccountsVisited=$AccountsVisited/$AccountsInScope Targets=$Targets Updated=$Updated AlreadyPresent=$AlreadyPresent Verified=$Verified WriteAttempts=$WriteAttempts Errors=$($Errors.Count) Report=$ReportPath"
    }
    Write-Output $FinalOutput
    exit 0
}
